-- LytHouse launch lifecycle core. Tenant ownership is enforced by the existing is_workspace_member(uuid) helper.
create table if not exists public.change_requests (id uuid primary key default gen_random_uuid(),workspace_id uuid not null references public.workspaces(id) on delete cascade,project_id uuid not null references public.projects(id) on delete cascade,environment_id uuid references public.environments(id) on delete set null,validation_id uuid references public.validations(id) on delete set null,created_by uuid not null default auth.uid(),title text not null,description text,status text not null default 'draft' check(status in('draft','validating','review','approved','rejected','deployed','failed')),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.policy_evaluations (id uuid primary key default gen_random_uuid(),workspace_id uuid not null references public.workspaces(id) on delete cascade,project_id uuid not null references public.projects(id) on delete cascade,change_request_id uuid not null references public.change_requests(id) on delete cascade,validation_id uuid references public.validations(id) on delete set null,policy_key text not null,result text not null check(result in('pass','warn','fail')),evidence jsonb not null default '{}'::jsonb,created_at timestamptz not null default now());
create table if not exists public.approvals (id uuid primary key default gen_random_uuid(),workspace_id uuid not null references public.workspaces(id) on delete cascade,change_request_id uuid not null references public.change_requests(id) on delete cascade,requested_by uuid not null default auth.uid(),decided_by uuid,status text not null default 'pending' check(status in('pending','approved','rejected')),note text,created_at timestamptz not null default now(),decided_at timestamptz);
create table if not exists public.deployments (id uuid primary key default gen_random_uuid(),workspace_id uuid not null references public.workspaces(id) on delete cascade,project_id uuid not null references public.projects(id) on delete cascade,environment_id uuid references public.environments(id) on delete set null,change_request_id uuid not null references public.change_requests(id) on delete restrict,validation_id uuid references public.validations(id) on delete set null,status text not null default 'pending' check(status in('pending','running','succeeded','failed','rolled_back')),provider text,external_id text,deployed_by uuid default auth.uid(),started_at timestamptz,completed_at timestamptz,created_at timestamptz not null default now());
create table if not exists public.incidents (id uuid primary key default gen_random_uuid(),workspace_id uuid not null references public.workspaces(id) on delete cascade,project_id uuid not null references public.projects(id) on delete cascade,environment_id uuid references public.environments(id) on delete set null,deployment_id uuid references public.deployments(id) on delete set null,title text not null,severity text not null default 'medium' check(severity in('low','medium','high','critical')),status text not null default 'open' check(status in('open','investigating','resolved')),description text,created_by uuid default auth.uid(),created_at timestamptz not null default now(),resolved_at timestamptz);
create index if not exists change_requests_ws_idx on public.change_requests(workspace_id,created_at desc);create index if not exists policy_eval_change_idx on public.policy_evaluations(change_request_id);create index if not exists approvals_change_idx on public.approvals(change_request_id);create index if not exists deployments_change_idx on public.deployments(change_request_id);create index if not exists incidents_deployment_idx on public.incidents(deployment_id);
do $$declare t text;begin foreach t in array array['change_requests','policy_evaluations','approvals','deployments','incidents'] loop execute format('alter table public.%I enable row level security',t);execute format('drop policy if exists lythouse_workspace_access on public.%I',t);execute format('create policy lythouse_workspace_access on public.%I for all to authenticated using (public.is_workspace_member(workspace_id)) with check (public.is_workspace_member(workspace_id))',t);end loop;end$$;